CHUNK = 1024 * 1024

def _hash_file(path):
    digest = hashlib.sha256()
    with path.open('rb') as handle:
        while True:
            data = handle.read(CHUNK)
            if not data:
                return digest.hexdigest()
            digest.update(data)
